import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

router.post('/parse-resume', upload.single('resume'), async (req: MulterRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume file uploaded.' });
      return;
    }

    if (req.file.mimetype !== 'application/pdf') {
      res.status(400).json({ error: 'Invalid file type. Only PDF is supported.' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const extractedText = parsedPdf.text;

    res.status(200).json({
      success: true,
      fileName: req.file.originalname,
      pageCount: parsedPdf.numpages,
      text: extractedText,
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF resume.', details: error.message });
  }
});

export default router;

import React, { useState, useMemo } from 'react';

interface AnalysisResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

export const KeywordMatchScorer: React.FC<{ resumeText: string; jobDescription: string }> = ({
  resumeText,
  jobDescription,
}) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const analysis = useMemo<AnalysisResult>(() => {
    if (!jobDescription || !resumeText) {
      return { score: 0, matchedKeywords: [], missingKeywords: [] };
    }

    const cleanText = (text: string) =>
      Array.from(
        new Set(
          text
            .toLowerCase()
            .replace(/[^\w\s]/gi, '')
            .split(/\s+/
        )
      ).filter((word) => word.length > 2);

    const jobWords = cleanText(jobDescription);
    const resumeWords = new Set(cleanText(resumeText));

    const matched: string[] = [];
    const missing: string[] = [];

    jobWords.forEach((word) => {
      if (resumeWords.has(word)) {
        matched.push(word);
      } else {
        missing.push(word);
      }
    });

    const score = jobWords.length > 0 ? Math.round((matched.length / jobWords.length) * 100) : 0;

    return { score, matchedKeywords: matched, missingKeywords: missing };
  }, [resumeText, jobDescription]);

  return (
    <div className="p-6 bg-white rounded-xl shadow-md space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-bold text-gray-800">AI Match Score</h3>
        <span className="text-3xl font-extrabold text-indigo-600">{analysis.score}%</span>
      </div>
      <div className="w-full bg-gray-200 rounded-full h-4">
        <div
          className="bg-indigo-600 h-4 rounded-full transition-all duration-500"
          style={{ width: `${analysis.score}%` }}
        />
      </div>
      <div className="grid grid-cols-2 gap-4 pt-2">
        <div className="bg-green-50 p-3 rounded-lg">
          <h4 className="font-semibold text-green-800 text-sm">Matched Keywords ({analysis.matchedKeywords.length})</h4>
          <div className="flex flex-wrap gap-1 mt-2">
            {analysis.matchedKeywords.slice(0, 10).map((kw) => (
              <span key={kw} className="px-2 py-0.5 bg-green-200 text-green-800 text-xs rounded">
                {kw}
              </span>
            ))}
          </div>
        </div>
        <div className="bg-red-50 p-3 rounded-lg">
          <h4 className="font-semibold text-red-800 text-sm">Missing Keywords ({analysis.missingKeywords.length})</h4>
          <div className="flex flex-wrap gap-1 mt-2">
            {analysis.missingKeywords.slice(0, 10).map((kw) => (
              <span key={kw} className="px-2 py-0.5 bg-red-200 text-red-800 text-xs rounded">
                {kw}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};
